+        margin: 0 0 0.5rem;
+        color: var(--accent-strong);
+        font-size: 0.875rem;
+        letter-spacing: 0.08em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(1.75rem, 4vw, 2.25rem);
+        line-height: 1.1;
+      }
+
+      .description {
+        margin: 0.875rem 0 1.5rem;
+        color: var(--muted);
+      }
+
+      form {
+        display: grid;
+        gap: 1.25rem;
+      }
+
+      .form-field {
+        padding: 1rem;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        background: var(--bg-soft);
+      }
+
+      .checkbox-row {
+        display: flex;
+        gap: 0.75rem;
+        align-items: flex-start;
+      }
+
+      .checkbox-row input {
+        margin: 0.2rem 0 0;
+        width: 1.1rem;
+        height: 1.1rem;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      .checkbox-copy {
+        display: grid;
+        gap: 0.25rem;
+      }
+
+      label {
+        font-weight: 600;
+      }
+
+      .required-mark {
+        color: var(--accent-strong);
+      }
+
+      .helper-text {
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-start;
+      }
+
+      button {
+        appearance: none;
+        border: 1px solid transparent;
+        border-radius: 999px;
+        padding: 0.85rem 1.25rem;
+        font: inherit;
+        font-weight: 700;
+        color: #101524;
+        background: linear-gradient(180deg, var(--accent-strong) 0%, var(--accent) 100%);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.06);
+      }
+
+      button:active {
+        transform: translateY(1px);
+      }
+
+      :focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 0;
+        color: var(--accent-strong);
+        font-weight: 600;
+      }
+
+      @media (max-width: 420px) {
+        .card {
+          padding: 1.25rem;
+          border-radius: 1.125rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --bg: Canvas;
+          --bg-elevated: Canvas;
+          --bg-soft: Canvas;
+          --border: ButtonBorder;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --accent: Highlight;
+          --accent-strong: HighlightText;
+          --focus: Highlight;
+          --shadow: Canvas;
+        }
+
+        body,
+        .card,
+        .form-field,
+        button {
+          forced-color-adjust: auto;
+        }
+
+        .card,
+        .form-field,
+        button {
+          box-shadow: none;
+        }
+
+        .skip-link {
+          border: 1px solid ButtonText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main">Skip to main content</a>
+    <main id="main"></main>
+
+    <script>
+      const app = document.getElementById("main");
+
+      function ConsentField() {
+        return `
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="terms-consent"
+                name="termsConsent"
+                type="checkbox"
+                required
+                aria-describedby="consent-help consent-status"
+              />
+              <div class="checkbox-copy">
+                <label for="terms-consent">
+                  I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
+                </label>
+                <p class="helper-text" id="consent-help">Required to continue.</p>
+              </div>
+            </div>
+          </div>
+        `;
+      }
+
+      function App() {
+        return `
+          <section class="card" aria-labelledby="page-title">
+            <p class="eyebrow">Consent</p>
+            <h1 id="page-title">Agree to the terms</h1>
+            <p class="description">Please confirm your agreement before submitting the form.</p>
+
+            <form id="consent-form" novalidate>
+              ${ConsentField()}
+              <div class="actions">
+                <button type="submit">Submit</button>
+              </div>
+              <p class="status" id="consent-status" aria-live="polite"></p>
+            </form>
+          </section>
+        `;
+      }
+
+      app.innerHTML = App();
+
+      const form = document.getElementById("consent-form");
+      const status = document.getElementById("consent-status");
+
+      form.addEventListener("submit", (event) => {
+        if (!form.checkValidity()) {
+          event.preventDefault();
+          const firstInvalid = form.querySelector(":invalid");
+          if (firstInvalid) {
+            firstInvalid.focus();
+          }
+          status.textContent = "";
+          form.reportValidity();
+          return;
+        }
+
+        event.preventDefault();
+        status.textContent = "Consent recorded.";
+      });
+    </script>
+  </body>
+</html>
*** End Patch
