        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, var(--bg-elevated) 0%, #0f172c 100%);
        box-shadow: 0 24px 60px var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent-strong);
        font-size: 0.875rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4vw, 2.25rem);
        line-height: 1.1;
      }

      .description {
        margin: 0.875rem 0 1.5rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: var(--bg-soft);
      }

      .checkbox-row {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
      }

      .checkbox-row input {
        margin: 0.2rem 0 0;
        width: 1.1rem;
        height: 1.1rem;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .checkbox-copy {
        display: grid;
        gap: 0.25rem;
      }

      label {
        font-weight: 600;
      }

      .required-mark {
        color: var(--accent-strong);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .actions {
        display: flex;
        justify-content: flex-start;
      }

      button {
        appearance: none;
        border: 1px solid transparent;
