      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --bg-elevated: Canvas;
          --bg-soft: Canvas;
          --border: ButtonBorder;
          --text: CanvasText;
          --muted: CanvasText;
          --accent: Highlight;
          --accent-strong: HighlightText;
          --focus: Highlight;
          --shadow: Canvas;
        }

        body,
        .card,
        .form-field,
        button {
          forced-color-adjust: auto;
        }

        .card,
        .form-field,
        button {
          box-shadow: none;
        }

        .skip-link {
          border: 1px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main"></main>

    <script>
      const app = document.getElementById("main");

      function ConsentField() {
        return `
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="terms-consent"
                name="termsConsent"
                type="checkbox"
                required
                aria-describedby="consent-help consent-status"
              />
              <div class="checkbox-copy">
                <label for="terms-consent">
                  I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
                </label>
                <p class="helper-text" id="consent-help">Required to continue.</p>
              </div>
            </div>
          </div>
        `;
      }

      function App() {
        return `
          <section class="card" aria-labelledby="page-title">
            <p class="eyebrow">Consent</p>
            <h1 id="page-title">Agree to the terms</h1>
            <p class="description">Please confirm your agreement before submitting the form.</p>

            <form id="consent-form" novalidate>
              ${ConsentField()}
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <p class="status" id="consent-status" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      app.innerHTML = App();

      const form = document.getElementById("consent-form");
      const status = document.getElementById("consent-status");

      form.addEventListener("submit", (event) => {
        if (!form.checkValidity()) {
          event.preventDefault();
          const firstInvalid = form.querySelector(":invalid");
          if (firstInvalid) {
            firstInvalid.focus();
          }
          status.textContent = "";
          form.reportValidity();
          return;
        }

        event.preventDefault();
        status.textContent = "Consent recorded.";
      });
    </script>
  </body>
